+    (function () {
+      const carousel = document.querySelector('.carousel');
+      if (!carousel) return;
+
+      function setSnappedItem(targetItem) {
+        const items = carousel.querySelectorAll('.carousel-item');
+        items.forEach((item) => {
+          const isTarget = item === targetItem;
+          item.classList.toggle('snapped', isTarget);
+          item.classList.toggle('active', isTarget);
+          item.classList.toggle('is-snapped', isTarget);
+          if (isTarget) {
+            item.setAttribute('data-snapped', 'true');
+          } else {
+            item.removeAttribute('data-snapped');
+          }
+        });
+      }
+
+      function updateSnappedByPosition() {
+        const items = carousel.querySelectorAll('.carousel-item');
+        if (!items.length) return;
+
+        const carouselRect = carousel.getBoundingClientRect();
+        const carouselCenter = carouselRect.left + carouselRect.width / 2;
+
+        let closestItem = items[0];
+        let minDistance = Infinity;
+
+        items.forEach((item) => {
+          const rect = item.getBoundingClientRect();
+          const itemCenter = rect.left + rect.width / 2;
+          const distance = Math.abs(itemCenter - carouselCenter);
+          if (distance < minDistance) {
+            minDistance = distance;
+            closestItem = item;
+          }
+        });
+
+        setSnappedItem(closestItem);
+      }
+
+      carousel.addEventListener('scroll', updateSnappedByPosition, { passive: true });
+      carousel.addEventListener('scrollend', updateSnappedByPosition, { passive: true });
