+  return pixel_buffer.data();
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* render(int w, int h, int samps) {
+  clear_accumulation(w, h);
+  return render_pass(w, h, samps, 0);
+}
+
+EMSCRIPTEN_KEEPALIVE
+uint8_t* get_pixel_buffer() {
+  return pixel_buffer.data();
+}
+
+EMSCRIPTEN_KEEPALIVE
+int get_total_samples() {
+  return total_samples_accumulated;
+}
+
+} // extern "C"
+
+int main(int argc, char *argv[]) {
+  int w=320, h=240, samps = argc==2 ? atoi(argv[1])/4 : 1; // # samples
+  render(w, h, samps);
+  FILE *f = fopen("image.ppm", "w");         // Write image to PPM file.
+  if (f) {
+    fprintf(f, "P3\n%d %d\n%d\n", w, h, 255);
+    for (int i=0; i<w*h; i++)
+      fprintf(f,"%d %d %d ", pixel_buffer[i*4], pixel_buffer[i*4+1], pixel_buffer[i*4+2]);
+    fclose(f);
+  }
+  return 0;
+}
