+  <script>
+    (function () {
+      const themeSelect = document.getElementById('theme-select');
+      const colorSchemeMeta = document.querySelector('meta[name="color-scheme"]');
+      const rootEl = document.documentElement;
+      const systemDarkQuery = window.matchMedia('(prefers-color-scheme: dark)');
+
+      function updateSystemOptionLabel() {
+        const systemOption = themeSelect.querySelector('option[value="light dark"]');
+        if (systemOption) {
+          const currentSystem = systemDarkQuery.matches ? 'dark' : 'light';
+          systemOption.textContent = `System Default (Currently ${currentSystem})`;
+        }
+      }
+
+      function applyTheme(value, persist = true) {
+        const scheme = (value === 'light' || value === 'dark') ? value : 'light dark';
+        if (colorSchemeMeta) {
+          colorSchemeMeta.content = scheme;
+        }
+        rootEl.style.colorScheme = scheme;
+        if (scheme === 'light' || scheme === 'dark') {
+          rootEl.setAttribute('data-theme', scheme);
+        } else {
+          rootEl.removeAttribute('data-theme');
+        }
+        if (themeSelect && themeSelect.value !== scheme) {
+          themeSelect.value = scheme;
+        }
+
+        if (persist) {
+          try {
+            if (scheme === 'light dark') {
+              localStorage.removeItem('color-scheme');
+            } else {
+              localStorage.setItem('color-scheme', scheme);
+            }
+          } catch (e) {
+            // Ignore storage errors
+          }
+        }
+      }
+
+      // Initialize state from storage or meta
+      let initialScheme = 'light dark';
+      try {
+        initialScheme = localStorage.getItem('color-scheme') ?? 'light dark';
+      } catch (e) {
+        initialScheme = colorSchemeMeta ? colorSchemeMeta.content : 'light dark';
+      }
+      updateSystemOptionLabel();
+      applyTheme(initialScheme, false);
+
+      // Listen for manual user selection
+      themeSelect.addEventListener('change', (event) => {
+        applyTheme(event.target.value, true);
+      });
+
+      // Keep label updated when OS color scheme changes
+      systemDarkQuery.addEventListener('change', () => {
+        updateSystemOptionLabel();
+      });
+
+      // Sync across tabs
+      window.addEventListener('storage', (event) => {
+        if (event.key === 'color-scheme') {
+          applyTheme(event.newValue ?? 'light dark', false);
+        }
+      });
+
+      // Filter late night specials menu
+      const specialsSelect = document.getElementById('specials-category');
+      const specialItems = document.querySelectorAll('.special-item');
+      if (specialsSelect) {
+        specialsSelect.addEventListener('change', (event) => {
+          const category = event.target.value;
+          specialItems.forEach((item) => {
+            item.hidden = category !== 'all' && item.dataset.category !== category;
+          });
+        });
+      }
+    })();
+  </script>
