+      const stateView = event.state && event.state.viewId;
+      const pathView = window.location.pathname.replace(/^\//, '') || 'home';
+      const targetView = stateView || (document.getElementById(pathView) ? pathView : 'home');
+      switchToView(targetView);
+    });
+
+    // Interactive state within Menu view (preserved across view switches)
+    const menuSearch = document.getElementById('menu-search');
+    const filterButtons = document.querySelectorAll('.filter-btn');
+    const menuCards = document.querySelectorAll('#menu-grid .card');
+
+    function filterMenu() {
+      const activeBtn = document.querySelector('.filter-btn[aria-pressed="true"]');
+      const activeCategory = activeBtn ? activeBtn.dataset.category : 'all';
+      const query = (menuSearch ? menuSearch.value : '').trim().toLowerCase();
+
+      menuCards.forEach(card => {
+        const matchesCategory = activeCategory === 'all' || card.dataset.category === activeCategory;
+        const matchesQuery = !query || card.textContent.toLowerCase().includes(query);
+        card.hidden = !(matchesCategory && matchesQuery);
+      });
+    }
+
+    filterButtons.forEach(btn => {
+      btn.addEventListener('click', () => {
+        filterButtons.forEach(b => b.setAttribute('aria-pressed', String(b === btn)));
+        filterMenu();
+      });
+    });
+
+    if (menuSearch) {
+      menuSearch.addEventListener('input', filterMenu);
+    }
+
+    document.querySelectorAll('.add-to-bag-btn').forEach(btn => {
+      btn.addEventListener('click', () => {
+        const count = Number(btn.dataset.addedCount || 0) + 1;
+        btn.dataset.addedCount = String(count);
+        btn.textContent = `Added (${count})`;
+      });
+    });
+
+    // Interactive state within Locations view (preserved across view switches)
+    const locationSearch = document.getElementById('location-search');
+    const locationCards = document.querySelectorAll('#locations-grid .card');
+
+    if (locationSearch) {
+      locationSearch.addEventListener('input', () => {
+        const query = locationSearch.value.trim().toLowerCase();
+        locationCards.forEach(card => {
+          card.hidden = Boolean(query && !card.textContent.toLowerCase().includes(query));
+        });
+      });
+    }
+
+    const storeButtons = document.querySelectorAll('.select-store-btn');
+    storeButtons.forEach(btn => {
+      btn.addEventListener('click', () => {
+        storeButtons.forEach(b => {
+          const isSelected = b === btn;
+          b.setAttribute('aria-pressed', String(isSelected));
+          b.textContent = isSelected ? 'Selected Pickup Store' : 'Set as Pickup Store';
+        });
+      });
+    });
+
+    // Interactive state within Rewards view (preserved across view switches)
+    const rewardsBalanceEl = document.getElementById('rewards-balance');
+    document.querySelectorAll('.redeem-btn').forEach(btn => {
+      btn.addEventListener('click', () => {
+        const cost = Number(btn.dataset.cost || 0);
+        const currentBalance = Number(rewardsBalanceEl.textContent || 0);
+        if (currentBalance >= cost) {
+          rewardsBalanceEl.textContent = String(currentBalance - cost);
+          btn.textContent = 'Redeemed!';
+          btn.disabled = true;
+        }
+      });
+    });
+
+    // Interactive state within My Account view (preserved across view switches)
+    const accountForm = document.getElementById('account-form');
+    const accountStatus = document.getElementById('account-status');
+    if (accountForm && accountStatus) {
+      accountForm.addEventListener('submit', event => {
+        event.preventDefault();
+        const nameInput = document.getElementById('account-name');
+        accountStatus.textContent = `Saved profile changes for ${nameInput ? nameInput.value : 'account'}.`;
+      });
+    }
+  </script>
 </body>

