+      // Maps the element's border box (CSS pixels) to the canvas (CSS pixels), for a
+      // quad that spans -0.5 to 0.5 in model space and is drawn with the `mvp` matrix.
+      function computeCanvasTransform(canvasEl, element, mvp) {
