+        const clipToCanvasViewport = new DOMMatrix()
+          // Move center (0,0) to center of canvas
+          .translate(canvasEl.clientWidth / 2, canvasEl.clientHeight / 2)
+          // Scale normalized clip (-1..1) to viewport size, and flip Y back
+          .scale(canvasEl.clientWidth / 2, -canvasEl.clientHeight / 2, canvasEl.clientHeight / 2);
