+      // Shaders for the 3D coffee box & textured HTML front face
+      const vsSource = `#version 300 es
+        in vec3 aPosition;
+        in vec2 aTexCoord;
+        in vec3 aColor;
+        uniform mat4 uMVP;
+        out vec2 vTexCoord;
+        out vec3 vColor;
+        void main() {
+          gl_Position = uMVP * vec4(aPosition, 1.0);
+          vTexCoord = aTexCoord;
+          vColor = aColor;
+        }
+      `;
