+      const fsSource = `#version 300 es
+        precision mediump float;
+        in vec2 vTexCoord;
+        in vec3 vColor;
+        uniform sampler2D uTexture;
+        uniform bool uUseTexture;
+        out vec4 outColor;
+        void main() {
+          if (uUseTexture) {
+            outColor = texture(uTexture, vTexCoord);
+          } else {
+            outColor = vec4(vColor, 1.0);
+          }
+        }
