+         0.5, -0.5,  0.5,   1.0, 1.0,   0.95, 0.90, 0.85,
+         0.5,  0.5,  0.5,   1.0, 0.0,   0.95, 0.90, 0.85,
+        -0.5,  0.5,  0.5,   0.0, 0.0,   0.95, 0.90, 0.85,
+
+        // Back face (z = -0.5) - Rich Espresso Brown
+         0.5, -0.5, -0.5,   0.0, 1.0,   0.31, 0.20, 0.18,
+        -0.5, -0.5, -0.5,   1.0, 1.0,   0.31, 0.20, 0.18,
+        -0.5,  0.5, -0.5,   1.0, 0.0,   0.31, 0.20, 0.18,
+         0.5,  0.5, -0.5,   0.0, 0.0,   0.31, 0.20, 0.18,
+
+        // Top face (y = 0.5) - Warm Amber Accent
+        -0.5,  0.5,  0.5,   0.0, 1.0,   0.85, 0.65, 0.45,
+         0.5,  0.5,  0.5,   1.0, 1.0,   0.85, 0.65, 0.45,
+         0.5,  0.5, -0.5,   1.0, 0.0,   0.85, 0.65, 0.45,
+        -0.5,  0.5, -0.5,   0.0, 0.0,   0.85, 0.65, 0.45,
+
+        // Bottom face (y = -0.5) - Dark Roast
+        -0.5, -0.5, -0.5,   0.0, 1.0,   0.24, 0.15, 0.14,
+         0.5, -0.5, -0.5,   1.0, 1.0,   0.24, 0.15, 0.14,
+         0.5, -0.5,  0.5,   1.0, 0.0,   0.24, 0.15, 0.14,
+        -0.5, -0.5,  0.5,   0.0, 0.0,   0.24, 0.15, 0.14,
+
+        // Right face (x = 0.5) - Medium Roast Side
+         0.5, -0.5,  0.5,   0.0, 1.0,   0.43, 0.30, 0.25,
+         0.5, -0.5, -0.5,   1.0, 1.0,   0.43, 0.30, 0.25,
+         0.5,  0.5, -0.5,   1.0, 0.0,   0.43, 0.30, 0.25,
+         0.5,  0.5,  0.5,   0.0, 0.0,   0.43, 0.30, 0.25,
+
+        // Left face (x = -0.5) - Medium Roast Side
+        -0.5, -0.5, -0.5,   0.0, 1.0,   0.48, 0.34, 0.28,
+        -0.5, -0.5,  0.5,   1.0, 1.0,   0.48, 0.34, 0.28,
+        -0.5,  0.5,  0.5,   1.0, 0.0,   0.48, 0.34, 0.28,
