+import type { APIRoute } from 'astro';
+import { generateRegistrationOptions } from '@simplewebauthn/server';
+import { passkeyStore, RP_ID, RP_NAME } from '../../../utils/passkeys-store';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  const body = await request.json().catch(() => ({}));
+  const isPromotionFlow = Boolean(body?.promotion);
+
+  const user = (await session?.get('userProfile')) || passkeyStore.getUser();
+  const userExistingCredentials =
+    (await session?.get('passkeyCredentials')) ||
+    passkeyStore.findCredentialsByUserId(user.passkeyUserId);
+
+  const options = await generateRegistrationOptions({
+    rpName: RP_NAME,
+    rpID: RP_ID,
+    userID: Buffer.from(user.passkeyUserId, 'base64url'),
+    userName: user.name,
+    userDisplayName: user.displayName,
+    attestationType: 'none',
+    excludeCredentials: userExistingCredentials.map((cred: any) => ({
+      id: cred.id,
+      transports: cred.transports,
+    })),
+    authenticatorSelection: {
+      residentKey: 'required',
+      requireResidentKey: true,
+      userVerification: 'preferred',
+      ...(isPromotionFlow ? { authenticatorAttachment: 'platform' } : {}),
+    },
+    supportedAlgorithmIDs: [-7, -257],
+  });
+
+  await session?.set('passkeyChallenge', options.challenge);
+
+  return new Response(JSON.stringify(options), {
+    status: 200,
+    headers: { 'Content-Type': 'application/json' },
+  });
+};
