+import type { APIRoute } from 'astro';
+import { passkeyStore, RP_ID } from '../../utils/passkeys-store';
+
+export const GET: APIRoute = async ({ session }) => {
+  const user = (await session?.get('userProfile')) || passkeyStore.getUser();
+  return new Response(
+    JSON.stringify({
+      ...user,
+      rpId: RP_ID,
+      userId: user.passkeyUserId,
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
+
+export const PUT: APIRoute = async ({ request, session }) => {
+  const body = await request.json().catch(() => ({}));
+  const { name, displayName } = body;
+
+  const updatedUser = passkeyStore.updateUser({ name, displayName });
+  await session?.set('userProfile', updatedUser);
+
+  return new Response(
+    JSON.stringify({
+      ...updatedUser,
