+}
+
+// Build the paired Content-Security-Policy header for cross-browser defense-in-depth.
+export function buildContentSecurityPolicyHeader({
+  nonce,
+  reportTo = 'conn-reports',
+} = {}) {
+  const scriptSrc = nonce
+    ? `script-src 'self' 'nonce-${nonce}' 'strict-dynamic' 'report-sample'`
+    : `script-src 'self' 'report-sample'`;
+  const styleSrc = nonce
+    ? `style-src 'self' 'nonce-${nonce}'`
+    : `style-src 'self'`;
+
+  return [
+    "default-src 'self'",
+    "connect-src 'self'",
+    `img-src 'self' ${UNSPLASH_ORIGIN} data: blob:`,
+    scriptSrc,
+    styleSrc,
+    "form-action 'self'",
+    "worker-src 'self'",
+    "object-src 'none'",
+    "base-uri 'self'",
+    "frame-ancestors 'none'",
+    `report-to ${reportTo}`,
+  ].join('; ');
+}
+
+// Apply Connection-Allowlist, Content-Security-Policy, and Reporting-Endpoints
+// on document and worker responses.
+export function setConnectionAllowlistHeaders(res, options = {}) {
+  const {
+    secFetchDest = 'document',
+    patterns = DEFAULT_ALLOWLIST_PATTERNS,
+    reportOnlyPatterns,
+    reportEndpointName = 'conn-reports',
+    reportEndpointUrl = '/api/security-reports',
+    redirects = 'block',
+    webrtc = 'block',
+    reportOnly = false,
+    nonce,
+  } = options;
+
+  const setHeader = (name, value) =>
+    typeof res.setHeader === 'function' ? res.setHeader(name, value) : res.headers.set(name, value);
+
+  if (typeof res.appendHeader === 'function') {
+    res.appendHeader('Vary', 'Sec-Fetch-Dest');
+  } else if (typeof res.headers?.append === 'function') {
+    res.headers.append('Vary', 'Sec-Fetch-Dest');
+  } else {
+    setHeader('Vary', 'Sec-Fetch-Dest');
+  }
+
+  setHeader('X-Content-Type-Options', 'nosniff');
+  setHeader('X-Frame-Options', 'DENY');
+  setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
+
+  if (secFetchDest && !ALLOWLIST_DESTS.has(String(secFetchDest).toLowerCase())) return;
+
+  setHeader('Reporting-Endpoints', `${reportEndpointName}="${reportEndpointUrl}"`);
+  setHeader(
+    reportOnly ? 'Connection-Allowlist-Report-Only' : 'Connection-Allowlist',
+    buildConnectionAllowlistHeader({ allowSelf: true, patterns, reportTo: reportEndpointName, redirects, webrtc }),
+  );
+
+  if (!reportOnly && Array.isArray(reportOnlyPatterns)) {
+    setHeader(
+      'Connection-Allowlist-Report-Only',
+      buildConnectionAllowlistHeader({
+        allowSelf: true,
+        patterns: reportOnlyPatterns,
+        reportTo: reportEndpointName,
+        redirects,
+        webrtc,
+      }),
+    );
+  }
+
+  setHeader(
+    'Content-Security-Policy',
+    buildContentSecurityPolicyHeader({ nonce, reportTo: reportEndpointName }),
+  );
+}
+
+function readRequestBody(req) {
+  return new Promise((resolve, reject) => {
+    const chunks = [];
+    req.on('data', (chunk) => chunks.push(chunk));
+    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
+    req.on('error', reject);
+  });
+}
+
+function parseEmailFromBody(rawBody, contentType = '') {
+  if (!rawBody) return '';
+  if (contentType.includes('application/json')) {
+    try {
+      const parsed = JSON.parse(rawBody);
+      return typeof parsed?.email === 'string' ? parsed.email.trim() : '';
+    } catch {
+      return '';
+    }
+  }
+  const params = new URLSearchParams(rawBody);
+  return (params.get('email') || '').trim();
+}
+
+function isValidEmail(email) {
+  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+}
+
+export async function handleRequest(req, res) {
+  const host = req.headers.host || `localhost:${PORT}`;
+  const url = new URL(req.url || '/', `http://${host}`);
+  const secFetchDest = req.headers['sec-fetch-dest'] || 'document';
+  const reportEndpointUrl = `http://${host}/api/security-reports`;
+
+  // Handle violation reports from Reporting API
+  if (req.method === 'POST' && url.pathname === '/api/security-reports') {
+    const body = await readRequestBody(req);
+    try {
+      const parsed = JSON.parse(body);
+      securityReports.push(...(Array.isArray(parsed) ? parsed : [parsed]));
+    } catch {
+      // Ignore malformed report payloads
+    }
+    res.statusCode = 204;
+    res.end();
+    return;
+  }
+
+  // Handle newsletter signup submissions (supports both fetch JSON and standard HTML form POST)
+  if (req.method === 'POST' && (url.pathname === '/api/newsletter' || url.pathname === '/newsletter')) {
+    setConnectionAllowlistHeaders(res, {
+      secFetchDest: req.headers['sec-fetch-dest'] || 'empty',
+      reportEndpointUrl,
+    });
+    const rawBody = await readRequestBody(req);
+    const contentType = req.headers['content-type'] || '';
+    const email = parseEmailFromBody(rawBody, contentType);
+
+    if (!isValidEmail(email)) {
+      res.statusCode = 400;
+      res.setHeader('Content-Type', 'application/json; charset=utf-8');
+      res.end(
+        JSON.stringify({
+          ok: false,
+          message: 'Please enter a valid email address (for example, alex@example.com).',
+        }),
+      );
+      return;
+    }
+
+    subscribers.add(email.toLowerCase());
+    res.statusCode = 200;
+    res.setHeader('Content-Type', 'application/json; charset=utf-8');
+    res.end(
+      JSON.stringify({
+        ok: true,
+        email,
+        message: `Thanks for subscribing, ${email}! Check your inbox for fresh roast updates.`,
+      }),
+    );
+    return;
+  }
+
+  // Serve homepage
+  if (req.method === 'GET' && (url.pathname === '/' || url.pathname === '/index.html')) {
+    const nonce = crypto.randomBytes(16).toString('base64');
+    setConnectionAllowlistHeaders(res, {
+      secFetchDest,
+      reportEndpointUrl,
+      nonce,
+    });
+
+    const htmlPath = path.join(__dirname, 'index.html');
+    let html = await fs.readFile(htmlPath, 'utf8');
+    html = html.replaceAll('__CSP_NONCE__', nonce);
+
+    res.statusCode = 200;
+    res.setHeader('Content-Type', 'text/html; charset=utf-8');
+    res.end(html);
+    return;
+  }
+
+  res.statusCode = 404;
+  res.setHeader('Content-Type', 'application/json; charset=utf-8');
+  res.end(JSON.stringify({ ok: false, message: 'Not Found' }));
+}
+
+export function createAppServer() {
+  return http.createServer((req, res) => {
+    handleRequest(req, res).catch((err) => {
+      res.statusCode = 500;
+      res.setHeader('Content-Type', 'application/json; charset=utf-8');
+      res.end(JSON.stringify({ ok: false, message: err instanceof Error ? err.message : 'Internal Server Error' }));
+    });
+  });
+}
+
+if (process.argv[1] && path.resolve(process.argv[1]) === path.resolve(fileURLToPath(import.meta.url))) {
+  const server = createAppServer();
+  server.listen(PORT, () => {
+    console.log(`The Daily Grind server listening on http://localhost:${PORT}`);
+  });
+}

