+const http = require('http');
+const fs = require('fs');
+const path = require('path');
+
+let port = Number(process.env.PORT) || 11222;
+const portFlagIndex = process.argv.indexOf('--port');
+if (portFlagIndex !== -1 && process.argv[portFlagIndex + 1]) {
+  port = Number(process.argv[portFlagIndex + 1]) || port;
+}
+
+const CSP_POLICY = [
+  "default-src 'self'",
+  "script-src 'self' 'unsafe-inline'",
+  "style-src 'self' 'unsafe-inline'",
+  "img-src 'self' https://images.unsplash.com",
+  "connect-src 'self'",
+  "form-action 'self'",
+  "base-uri 'self'",
+  "frame-ancestors 'self'"
+].join('; ');
+
+const subscribers = [];
+
+const MIME_TYPES = {
+  '.html': 'text/html; charset=utf-8',
+  '.css': 'text/css; charset=utf-8',
+  '.js': 'application/javascript; charset=utf-8',
+  '.json': 'application/json; charset=utf-8',
+  '.png': 'image/png',
+  '.jpg': 'image/jpeg',
+  '.jpeg': 'image/jpeg',
+  '.svg': 'image/svg+xml',
+  '.ico': 'image/x-icon'
+};
+
+function setSecurityHeaders(res) {
+  res.setHeader('Content-Security-Policy', CSP_POLICY);
+  res.setHeader('X-Content-Type-Options', 'nosniff');
+}
+
+function parseEmailFromBody(rawBody, contentType = '') {
+  const trimmed = rawBody.trim();
+  if (!trimmed) return '';
+
+  if (contentType.includes('application/json') || trimmed.startsWith('{')) {
+    try {
+      const parsed = JSON.parse(trimmed);
+      if (typeof parsed.email === 'string') {
+        return parsed.email.trim();
+      }
+    } catch (_) {
+      // Fall through to URLSearchParams
+    }
+  }
+
+  const params = new URLSearchParams(trimmed);
+  if (params.has('email')) {
+    return (params.get('email') || '').trim();
+  }
+
+  return '';
+}
+
+const NEWSLETTER_PATHS = new Set([
+  '/newsletter',
+  '/api/newsletter',
+  '/subscribe',
+  '/api/subscribe',
+  '/signup',
+  '/api/signup'
+]);
+
+const server = http.createServer((req, res) => {
+  setSecurityHeaders(res);
+
+  const reqUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
+  const pathname = reqUrl.pathname;
+
+  if (req.method === 'POST' && (NEWSLETTER_PATHS.has(pathname) || pathname === '/')) {
+    let body = '';
+    req.on('data', (chunk) => {
+      body += chunk.toString();
+    });
+    req.on('end', () => {
+      const email = parseEmailFromBody(body, req.headers['content-type'] || '');
+      if (!email || !email.includes('@')) {
+        res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
+        res.end(JSON.stringify({
+          ok: false,
+          error: 'Please enter a valid email address.'
+        }));
+        return;
+      }
+
+      subscribers.push({ email, subscribedAt: new Date().toISOString() });
+      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+      res.end(JSON.stringify({
+        ok: true,
+        email,
+        message: 'Thank you for subscribing to The Daily Grind newsletter!'
+      }));
+    });
+    return;
+  }
+
+  if (req.method === 'GET' && (NEWSLETTER_PATHS.has(pathname) || pathname === '/subscribers')) {
+    res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
+    res.end(JSON.stringify({ ok: true, subscribers }));
+    return;
+  }
+
+  if (req.method === 'GET' && pathname === '/favicon.ico') {
+    res.writeHead(204);
+    res.end();
+    return;
+  }
+
+  if (req.method === 'GET' || req.method === 'HEAD') {
+    const relativePath = pathname === '/' ? '/index.html' : pathname;
+    const safePath = path.normalize(relativePath).replace(/^(\.\.[/\\])+/, '');
+    const filePath = path.join(__dirname, safePath);
+
+    if (!filePath.startsWith(__dirname)) {
+      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
+      res.end('Forbidden');
+      return;
+    }
+
+    fs.readFile(filePath, (err, content) => {
+      if (err) {
+        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
+        res.end('Not Found');
+        return;
+      }
+
+      const ext = path.extname(filePath).toLowerCase();
+      const contentType = MIME_TYPES[ext] || 'application/octet-stream';
+      res.writeHead(200, { 'Content-Type': contentType });
+      if (req.method === 'HEAD') {
+        res.end();
+      } else {
+        res.end(content);
+      }
+    });
+    return;
+  }
+
+  res.writeHead(405, { 'Content-Type': 'application/json; charset=utf-8' });
+  res.end(JSON.stringify({ ok: false, error: 'Method Not Allowed' }));
+});
+
+if (require.main === module) {
+  server.listen(port, () => {
+    console.log(`Server listening on http://localhost:${port}`);
+  });
+}
+
+module.exports = server;

