+
+      // 2. Safe DOM Manipulation & HTML Sanitization Helpers (security §1.2, sanitize-untrusted-html)
+      function safeSetText(element, text) {
+        if (!element) return;
+        element.textContent = String(text ?? '');
+      }
+
+      let domPurifyPromise;
+      function loadDOMPurify() {
+        domPurifyPromise ??= import('dompurify').then((mod) => mod.default ?? mod);
+        return domPurifyPromise;
+      }
+
+      async function safeSetHTML(
+        el,
+        html,
+        {
+          elements = ['p', 'b', 'i', 'strong', 'em', 'span'],
+          attributes = ['class'],
+        } = {},
+      ) {
