+      const logoutLink = document.querySelector('.logout-link');
+      if (logoutLink) {
+        logoutLink.addEventListener('click', () => {
+          try {
+            sessionStorage.clear();
+            localStorage.clear();
+          } catch {
+            // Ignore storage access errors in restricted contexts
+          }
+        });
+      }
