+        escapePolicy,
+        sanitizePolicy,
+        safeSetText,
+        safeSetHTML,
+        checkSameOriginWithFallback,
+        checkSameSiteWithFallback,
+        getCssUrlModifierSupport,
+        fetchWithPolicyHandling,
+        redactSensitiveUrl,
+      });
+    })();
