+      function navigateBack(options) {
+        options = options || {};
+        if (currentRoute.depth <= 0) return;
+
+        var parentRoute = currentRoute.depth === 2
+          ? { depth: 1, itemId: currentRoute.itemId, subView: null }
+          : { depth: 0, itemId: currentRoute.itemId, subView: null };
