+        if (inAppHistoryDepth > 0 && !options.forceDirectState) {
+          inAppHistoryDepth = Math.max(0, inAppHistoryDepth - 1);
+          if (options.alreadyAnimated) {
+            suppressNextPopTransition = true;
+          }
+          window.history.back();
+        } else {
+          // Opened directly via deep link in a new tab: transition to parent and sync URL
+          currentRoute = parentRoute;
+          applyStackVisualState(currentRoute, false);
+          var parentUrl = buildUrlForRoute(parentRoute);
+          try {
+            window.history.pushState({
+              depth: parentRoute.depth,
+              itemId: parentRoute.itemId,
+              subView: parentRoute.subView,
+              inAppDepth: 0
+            }, '', parentUrl);
+          } catch (err) {
+            preferHashRouting = true;
+            window.history.pushState({
+              depth: parentRoute.depth,
+              itemId: parentRoute.itemId,
+              subView: parentRoute.subView,
+              inAppDepth: 0
+            }, '', buildUrlForRoute(parentRoute));
+          }
+        }
+      }
+
+      // Sync with browser Back / Forward buttons and hash changes
+      window.addEventListener('popstate', function (event) {
+        var nextRoute = (event.state && typeof event.state.depth === 'number')
+          ? {
