+      });
+
+      // Delegated Click Handling for Drill-Down Cards, Links, and Back Buttons
+      document.addEventListener('click', function (event) {
+        // 1. Back action buttons
+        var backTrigger = event.target.closest('[data-action="back"]');
+        if (backTrigger) {
+          event.preventDefault();
+          navigateBack();
+          return;
+        }
+
+        // 2. Root home links / breadcrumbs
+        var rootTrigger = event.target.closest('[data-nav-root]');
