+          toast.classList.remove('visible');
+        }, 2600);
+      });
+
+      // ==================== INTERACTIVE SWIPE-BACK GESTURE ENGINE ====================
+      // Supports both Touch (touchstart/touchmove/touchend) and Pointer/Mouse drag to swipe back
