+        gesture.tracking = false;
+        gesture.lockedHorizontal = false;
+
+        if (!wasLocked) return;
+
+        if (gesture.activeScreen) {
+          gesture.activeScreen.classList.remove('is-dragging');
+          gesture.activeScreen.style.transform = '';
+        }
+        if (gesture.underScreen) {
+          gesture.underScreen.classList.remove('is-dragging');
+          gesture.underScreen.style.transform = '';
+          gesture.underScreen.style.filter = '';
+        }
+
+        var shouldPop = dx > Math.min(100, vw * 0.22) || (velocity > 0.42 && dx > 28);
+        if (shouldPop) {
+          // Immediately transition visual stack to parent, then sync history without double-animating
+          var parentRoute = currentRoute.depth === 2
+            ? { depth: 1, itemId: currentRoute.itemId, subView: null }
+            : { depth: 0, itemId: currentRoute.itemId, subView: null };
+          applyStackVisualState(parentRoute, false);
+          navigateBack({ alreadyAnimated: true });
+        } else {
+          // Snap back to current active view
+          applyStackVisualState(currentRoute, false);
+        }
+      }
+
+      // Touch event listeners
+      document.addEventListener('touchstart', function (e) {
+        if (!e.touches || e.touches.length !== 1) return;
+        onGestureStart(e.touches[0].clientX, e.touches[0].clientY, e.target);
+      }, { passive: true });
+
+      document.addEventListener('touchmove', function (e) {
+        if (!e.touches || e.touches.length !== 1) return;
+        onGestureMove(e.touches[0].clientX, e.touches[0].clientY, e);
+      }, { passive: false });
+
+      document.addEventListener('touchend', function () {
+        onGestureEnd();
+      });
+
+      document.addEventListener('touchcancel', function () {
+        onGestureEnd();
+      });
+
+      // Mouse / Pointer drag listeners for desktop swipe-back
+      var mouseDownActive = false;
+      document.addEventListener('mousedown', function (e) {
+        if (e.button !== 0 || currentRoute.depth <= 0) return;
+        mouseDownActive = true;
+        onGestureStart(e.clientX, e.clientY, e.target);
+      });
+
+      document.addEventListener('mousemove', function (e) {
+        if (!mouseDownActive) return;
+        onGestureMove(e.clientX, e.clientY, e);
+      });
+
+      document.addEventListener('mouseup', function () {
+        if (!mouseDownActive) return;
+        mouseDownActive = false;
+        onGestureEnd();
+      });
+
+      // Initial Boot & Deep Link Synchronization
+      var initialRoute = parseRouteFromLocation(window.location);
+      currentRoute = initialRoute;
+      applyStackVisualState(currentRoute, true);
+
+      try {
+        window.history.replaceState({
+          depth: currentRoute.depth,
+          itemId: currentRoute.itemId,
+          subView: currentRoute.subView,
+          inAppDepth: 0
+        }, '', window.location.href);
+      } catch (err) {
+        // Ignore replaceState restriction on file://
+      }
+    })();
+  </script>
