+      if (
+        parent !== element &&
+        (parent.tagName === 'P' ||
+          parent.tagName === 'LI' ||
+          parent.tagName === 'UL' ||
+          parent.tagName === 'OL' ||
+          parent.tagName === 'BLOCKQUOTE')
+      ) {
+        return NodeFilter.FILTER_REJECT;
+      }
+      if (!node.nodeValue || !node.nodeValue.trim()) {
+        return NodeFilter.FILTER_SKIP;
+      }
